"""SQLite data access layer for MediaPush.

All methods return plain dicts/lists; sqlite3 objects never leak out.
"""
from __future__ import annotations

import sqlite3
from datetime import datetime
from pathlib import Path
from typing import Optional


_SCHEMA = """
CREATE TABLE IF NOT EXISTS groups (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    name        TEXT NOT NULL,
    created_at  TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS accounts (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    group_id     INTEGER NOT NULL REFERENCES groups(id),
    platform     TEXT NOT NULL,
    display_name TEXT NOT NULL,
    profile_path TEXT NOT NULL,
    is_active    INTEGER NOT NULL DEFAULT 1
);

CREATE TABLE IF NOT EXISTS tasks (
    id             INTEGER PRIMARY KEY AUTOINCREMENT,
    video_path     TEXT NOT NULL,
    group_id       INTEGER NOT NULL REFERENCES groups(id),
    scheduled_time TEXT NOT NULL,
    status         TEXT NOT NULL DEFAULT 'pending',
    created_at     TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS task_logs (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    task_id       INTEGER NOT NULL REFERENCES tasks(id),
    account_id    INTEGER NOT NULL REFERENCES accounts(id),
    status        TEXT NOT NULL DEFAULT 'pending',
    error_msg     TEXT,
    submitted_at  TEXT,
    attempt_count INTEGER NOT NULL DEFAULT 1,
    next_retry_at TEXT
);
"""


class Store:
    def __init__(self, db_path: str):
        Path(db_path).parent.mkdir(parents=True, exist_ok=True)
        self._conn = sqlite3.connect(db_path, check_same_thread=False)
        self._conn.row_factory = sqlite3.Row
        self._conn.execute("PRAGMA foreign_keys = ON")
        self._init_schema()

    def _init_schema(self) -> None:
        self._conn.executescript(_SCHEMA)
        self._migrate()
        self._conn.commit()

    def _migrate(self) -> None:
        """Idempotent column additions for older DBs created before retry support."""
        cols = {row[1] for row in self._conn.execute("PRAGMA table_info(task_logs)")}
        if "attempt_count" not in cols:
            self._conn.execute("ALTER TABLE task_logs ADD COLUMN attempt_count INTEGER NOT NULL DEFAULT 1")
        if "next_retry_at" not in cols:
            self._conn.execute("ALTER TABLE task_logs ADD COLUMN next_retry_at TEXT")

    def close(self) -> None:
        self._conn.close()

    @staticmethod
    def _now() -> str:
        return datetime.now().isoformat(timespec="seconds")

    @staticmethod
    def _row_to_dict(row: sqlite3.Row) -> dict:
        return {k: row[k] for k in row.keys()}

    # ---- groups ----
    def create_group(self, name: str) -> int:
        cur = self._conn.execute(
            "INSERT INTO groups (name, created_at) VALUES (?, ?)",
            (name, self._now()),
        )
        self._conn.commit()
        return int(cur.lastrowid)

    def list_groups(self) -> list[dict]:
        rows = self._conn.execute("SELECT id, name, created_at FROM groups ORDER BY id").fetchall()
        return [self._row_to_dict(r) for r in rows]

    def rename_group(self, group_id: int, new_name: str) -> None:
        self._conn.execute("UPDATE groups SET name = ? WHERE id = ?", (new_name, group_id))
        self._conn.commit()

    def delete_group(self, group_id: int) -> None:
        """Delete a group. Caller must ensure no accounts reference it."""
        if self._conn.execute("SELECT 1 FROM accounts WHERE group_id = ? LIMIT 1", (group_id,)).fetchone():
            raise ValueError(f"group {group_id} still has accounts")
        self._conn.execute("DELETE FROM groups WHERE id = ?", (group_id,))
        self._conn.commit()

    # ---- accounts ----
    def add_account(self, group_id: int, platform: str, display_name: str, profile_path: str) -> int:
        cur = self._conn.execute(
            "INSERT INTO accounts (group_id, platform, display_name, profile_path) VALUES (?, ?, ?, ?)",
            (group_id, platform, display_name, profile_path),
        )
        self._conn.commit()
        return int(cur.lastrowid)

    def list_accounts(self, group_id: Optional[int] = None) -> list[dict]:
        if group_id is None:
            rows = self._conn.execute("SELECT * FROM accounts ORDER BY id").fetchall()
        else:
            rows = self._conn.execute(
                "SELECT * FROM accounts WHERE group_id = ? ORDER BY id", (group_id,)
            ).fetchall()
        return [self._row_to_dict(r) for r in rows]

    def update_account_active(self, account_id: int, is_active: int) -> None:
        self._conn.execute("UPDATE accounts SET is_active = ? WHERE id = ?", (is_active, account_id))
        self._conn.commit()

    def delete_account(self, account_id: int) -> None:
        self._conn.execute("DELETE FROM accounts WHERE id = ?", (account_id,))
        self._conn.commit()

    def update_account_display_name(self, account_id: int, name: str) -> None:
        self._conn.execute("UPDATE accounts SET display_name = ? WHERE id = ?", (name, account_id))
        self._conn.commit()

    def move_account_to_group(self, account_id: int, new_group_id: int) -> None:
        self._conn.execute("UPDATE accounts SET group_id = ? WHERE id = ?", (new_group_id, account_id))
        self._conn.commit()

    # ---- tasks ----
    def create_task(self, video_path: str, group_id: int, scheduled_time: str) -> int:
        cur = self._conn.execute(
            "INSERT INTO tasks (video_path, group_id, scheduled_time, created_at) VALUES (?, ?, ?, ?)",
            (video_path, group_id, scheduled_time, self._now()),
        )
        self._conn.commit()
        return int(cur.lastrowid)

    def update_task_status(self, task_id: int, status: str) -> None:
        self._conn.execute("UPDATE tasks SET status = ? WHERE id = ?", (status, task_id))
        self._conn.commit()

    def list_tasks(self, status: Optional[str] = None) -> list[dict]:
        if status is None:
            rows = self._conn.execute("SELECT * FROM tasks ORDER BY id").fetchall()
        else:
            rows = self._conn.execute("SELECT * FROM tasks WHERE status = ? ORDER BY id", (status,)).fetchall()
        return [self._row_to_dict(r) for r in rows]

    # ---- task_logs ----
    def create_task_log(self, task_id: int, account_id: int) -> int:
        cur = self._conn.execute(
            "INSERT INTO task_logs (task_id, account_id) VALUES (?, ?)",
            (task_id, account_id),
        )
        self._conn.commit()
        return int(cur.lastrowid)

    def update_task_log_status(self, log_id: int, status: str, error_msg: Optional[str] = None) -> None:
        submitted_at = self._now() if status == "submitted" else None
        self._conn.execute(
            "UPDATE task_logs SET status = ?, error_msg = ?, submitted_at = ? WHERE id = ?",
            (status, error_msg, submitted_at, log_id),
        )
        self._conn.commit()

    def update_task_log_for_retry(self, log_id: int, next_retry_at: str) -> None:
        """Schedule a failed log for an automatic retry at the given ISO time.
        Status stays 'failed' until the sweeper picks it up."""
        self._conn.execute(
            "UPDATE task_logs SET next_retry_at = ? WHERE id = ?",
            (next_retry_at, log_id),
        )
        self._conn.commit()

    def list_task_logs_due_for_retry(self, now_iso: str) -> list[dict]:
        """Return failed logs whose next_retry_at has arrived."""
        rows = self._conn.execute(
            "SELECT * FROM task_logs WHERE status = 'failed' AND next_retry_at IS NOT NULL "
            "AND next_retry_at <= ? ORDER BY id",
            (now_iso,),
        ).fetchall()
        return [self._row_to_dict(r) for r in rows]

    def bump_attempt_and_requeue(self, log_id: int, new_attempt_count: int) -> None:
        """Reset a failed log back to pending for a fresh upload attempt."""
        self._conn.execute(
            "UPDATE task_logs SET status = 'pending', error_msg = NULL, "
            "next_retry_at = NULL, attempt_count = ? WHERE id = ?",
            (new_attempt_count, log_id),
        )
        self._conn.commit()

    def list_task_logs(self, task_id: Optional[int] = None) -> list[dict]:
        if task_id is None:
            rows = self._conn.execute("SELECT * FROM task_logs ORDER BY id").fetchall()
        else:
            rows = self._conn.execute(
                "SELECT * FROM task_logs WHERE task_id = ? ORDER BY id", (task_id,)
            ).fetchall()
        return [self._row_to_dict(r) for r in rows]

    def delete_task_logs(self, log_ids: list[int]) -> dict:
        """Delete task_log rows by id and remove tasks left without logs.

        This is a history cleanup operation only; it intentionally does not
        delete video files from disk.
        """
        ids = sorted({int(i) for i in log_ids})
        if not ids:
            return {"task_logs": 0, "tasks": 0}

        placeholders = ",".join("?" for _ in ids)
        cur = self._conn.execute(
            f"DELETE FROM task_logs WHERE id IN ({placeholders})",
            ids,
        )
        deleted_logs = cur.rowcount if cur.rowcount is not None else 0

        cur = self._conn.execute(
            """
            DELETE FROM tasks
            WHERE id NOT IN (SELECT DISTINCT task_id FROM task_logs)
            """
        )
        deleted_tasks = cur.rowcount if cur.rowcount is not None else 0
        self._conn.commit()
        return {"task_logs": deleted_logs, "tasks": deleted_tasks}

    def purge_submitted_history_before(self, cutoff_date: str) -> dict:
        """Delete submitted history rows before cutoff_date (YYYY-MM-DD).

        The history date is the scheduled publish date when present; immediate
        publishes fall back to submitted_at, then task created_at. Failed,
        pending, and uploading rows are intentionally kept so users can still
        inspect and retry actionable records.
        """
        cur = self._conn.execute(
            """
            DELETE FROM task_logs
            WHERE id IN (
                SELECT tl.id
                FROM task_logs tl
                JOIN tasks t ON t.id = tl.task_id
                WHERE tl.status = 'submitted'
                  AND date(
                      COALESCE(
                          NULLIF(t.scheduled_time, ''),
                          NULLIF(tl.submitted_at, ''),
                          t.created_at
                      )
                  ) < date(?)
            )
            """,
            (cutoff_date,),
        )
        deleted_logs = cur.rowcount if cur.rowcount is not None else 0

        cur = self._conn.execute(
            """
            DELETE FROM tasks
            WHERE id NOT IN (SELECT DISTINCT task_id FROM task_logs)
            """
        )
        deleted_tasks = cur.rowcount if cur.rowcount is not None else 0
        self._conn.commit()
        return {"task_logs": deleted_logs, "tasks": deleted_tasks}

"""Douyin stranger-message scraping and manual reply support.

Selectors are documented in docs/selectors_message.md. When Douyin changes
the creator-message page, update these constants first.
"""
from __future__ import annotations

import re
from datetime import datetime
from pathlib import Path

from publisher.message_reader import ChatMessage, Message, MessageReader


URL_CHAT = "https://creator.douyin.com/creator-micro/data/following/chat"

SEL_CONV_ITEMS = "li.semi-list-item"
SEL_CONV_USERNAME = '[class^="item-header-name-"]'
SEL_CONV_AVATAR = "img"
SEL_CONV_PREVIEW = '[class^="item-content-"] [class^="text-"]'
SEL_CONV_TIME = '[class^="item-header-time-"]'
SEL_CONV_UNREAD = ".semi-badge-primary"

SEL_REPLY_INPUT = '.chat-input-nSWBco[contenteditable="true"]'
SEL_REPLY_SEND = 'button.chat-btn:has-text("发送")'
SEL_REPLY_HISTORY_MESSAGES = '[class^="box-item-message-"] pre'
SEL_DETAIL_READY = SEL_REPLY_INPUT

NAV_TIMEOUT_MS = 20_000
TAB_SWITCH_WAIT_MS = 1_500
AFTER_SEND_SETTLE_MS = 5_000


def normalize_avatar_url(url: str) -> str:
    if url.startswith("//"):
        return "https:" + url
    return url


def conversation_id_from_parts(user_name: str, avatar_url: str) -> str:
    """Build a stable-enough id from fields Douyin exposes in the DOM."""
    avatar_path = avatar_url.split("?", 1)[0].rstrip("/")
    avatar_id = avatar_path.rsplit("/", 1)[-1] if avatar_path else ""
    raw = f"{user_name}_{avatar_id}" if avatar_id else user_name
    return re.sub(r"\s+", " ", raw).strip()


def _safe_inner_text(locator, timeout: int = 1000) -> str:
    try:
        return locator.inner_text(timeout=timeout).strip()
    except Exception:
        return ""


def _safe_attr(locator, attr: str, timeout: int = 1000) -> str:
    try:
        return locator.get_attribute(attr, timeout=timeout) or ""
    except Exception:
        return ""


class DouyinMessageReader(MessageReader):
    platform = "douyin"

    def fetch_unread_strangers(
        self,
        account_id: int,
        account_name: str,
        profile_path: str,
    ) -> list[Message]:
        from playwright.sync_api import sync_playwright

        user_data_dir = Path(profile_path).as_posix()
        results: dict[str, Message] = {}
        try:
            with sync_playwright() as p:
                ctx = p.chromium.launch_persistent_context(
                    user_data_dir=user_data_dir,
                    headless=True,
                    viewport={"width": 1280, "height": 800},
                )
                try:
                    page = ctx.pages[0] if ctx.pages else ctx.new_page()
                    page.goto(URL_CHAT, wait_until="domcontentloaded", timeout=NAV_TIMEOUT_MS)
                    for tab_name in ("全部", "陌生人私信"):
                        self._open_message_tab(page, tab_name)
                        for message in self._scrape_unread_visible_items(page, account_id, account_name):
                            results[message.conversation_id] = message
                finally:
                    ctx.close()
        except Exception:
            return []
        return list(results.values())

    def reply(self, profile_path: str, conversation_id: str, text: str) -> tuple[bool, str]:
        from playwright.sync_api import sync_playwright

        if not text.strip():
            return (False, "empty reply text")

        user_data_dir = Path(profile_path).as_posix()
        try:
            with sync_playwright() as p:
                ctx = p.chromium.launch_persistent_context(
                    user_data_dir=user_data_dir,
                    headless=True,
                    viewport={"width": 1280, "height": 800},
                )
                try:
                    page = ctx.pages[0] if ctx.pages else ctx.new_page()
                    page.goto(URL_CHAT, wait_until="domcontentloaded", timeout=NAV_TIMEOUT_MS)
                    target = self._find_conversation_item_in_tabs(page, conversation_id)
                    if target is None:
                        return (False, f"conversation not found: {conversation_id}")

                    target.click(timeout=NAV_TIMEOUT_MS)
                    page.locator(SEL_REPLY_INPUT).first.wait_for(
                        state="visible",
                        timeout=NAV_TIMEOUT_MS,
                    )
                    input_box = page.locator(SEL_REPLY_INPUT).first
                    input_box.click()
                    page.keyboard.press("Control+A")
                    page.keyboard.press("Delete")
                    page.keyboard.insert_text(text)

                    send_button = page.locator(SEL_REPLY_SEND).first
                    page.wait_for_function(
                        """() => {
                            const btn = Array.from(document.querySelectorAll('button.chat-btn'))
                                .find(b => (b.innerText || '').trim() === '发送');
                            return !!btn && !btn.disabled && !btn.className.includes('semi-button-disabled');
                        }""",
                        timeout=NAV_TIMEOUT_MS,
                    )
                    send_button.click(timeout=NAV_TIMEOUT_MS)
                    page.wait_for_function(
                        """(text) => {
                            const input = document.querySelector('.chat-input-nSWBco[contenteditable="true"]');
                            const empty = !input || !(input.innerText || '').trim();
                            const messages = Array.from(document.querySelectorAll('[class^="box-item-message-"] pre'))
                                .map(el => (el.innerText || '').trim());
                            return empty && messages.includes(text);
                        }""",
                        arg=text,
                        timeout=NAV_TIMEOUT_MS,
                    )
                    page.wait_for_timeout(AFTER_SEND_SETTLE_MS)
                    return (True, "")
                finally:
                    ctx.close()
        except Exception as exc:
            return (False, f"{type(exc).__name__}: {exc}")

    def fetch_conversation_messages(self, profile_path: str, conversation_id: str) -> list[ChatMessage]:
        from playwright.sync_api import sync_playwright

        user_data_dir = Path(profile_path).as_posix()
        try:
            with sync_playwright() as p:
                ctx = p.chromium.launch_persistent_context(
                    user_data_dir=user_data_dir,
                    headless=True,
                    viewport={"width": 1280, "height": 800},
                )
                try:
                    page = ctx.pages[0] if ctx.pages else ctx.new_page()
                    page.goto(URL_CHAT, wait_until="domcontentloaded", timeout=NAV_TIMEOUT_MS)
                    target = self._find_conversation_item_in_tabs(page, conversation_id)
                    if target is None:
                        return []
                    target.click(timeout=NAV_TIMEOUT_MS)
                    page.locator(SEL_DETAIL_READY).first.wait_for(state="visible", timeout=NAV_TIMEOUT_MS)
                    page.wait_for_timeout(TAB_SWITCH_WAIT_MS)
                    return self._scrape_visible_chat_messages(page)
                finally:
                    ctx.close()
        except Exception:
            return []

    def _open_message_tab(self, page, tab_name: str) -> None:
        page.get_by_role("tab", name=tab_name).click(timeout=NAV_TIMEOUT_MS)
        page.wait_for_function(
            """() => {
                if (document.querySelectorAll('li.semi-list-item').length > 0) return true;
                return document.body.innerText.includes('没有更多');
            }""",
            timeout=NAV_TIMEOUT_MS,
        )
        page.wait_for_timeout(TAB_SWITCH_WAIT_MS)

    def _scrape_unread_visible_items(self, page, account_id: int, account_name: str) -> list[Message]:
        messages: list[Message] = []
        for item in page.locator(SEL_CONV_ITEMS).all():
            try:
                if item.locator(SEL_CONV_UNREAD).count() <= 0:
                    continue
                user_name = _safe_inner_text(item.locator(SEL_CONV_USERNAME).first)
                avatar = normalize_avatar_url(_safe_attr(item.locator(SEL_CONV_AVATAR).first, "src"))
                preview = _safe_inner_text(item.locator(SEL_CONV_PREVIEW).first)
                timestamp = _safe_inner_text(item.locator(SEL_CONV_TIME).first)
                conversation_id = conversation_id_from_parts(user_name, avatar)
                if not user_name or not conversation_id:
                    continue
                messages.append(
                    Message(
                        account_id=account_id,
                        account_name=account_name,
                        conversation_id=conversation_id,
                        user_name=user_name,
                        user_avatar_url=avatar,
                        preview=preview,
                        timestamp_str=timestamp,
                        fetched_at=datetime.now(),
                    )
                )
            except Exception:
                continue
        return messages

    def _find_conversation_item_in_tabs(self, page, conversation_id: str):
        for tab_name in ("全部", "陌生人私信"):
            self._open_message_tab(page, tab_name)
            target = self._find_conversation_item(page, conversation_id)
            if target is not None:
                return target
        return None

    def _find_conversation_item(self, page, conversation_id: str):
        for item in page.locator(SEL_CONV_ITEMS).all():
            user_name = _safe_inner_text(item.locator(SEL_CONV_USERNAME).first)
            avatar = normalize_avatar_url(_safe_attr(item.locator(SEL_CONV_AVATAR).first, "src"))
            if conversation_id_from_parts(user_name, avatar) == conversation_id:
                return item
        return None

    def _scrape_visible_chat_messages(self, page) -> list[ChatMessage]:
        rows = page.evaluate(
            """() => {
                const out = [];
                const pres = Array.from(document.querySelectorAll('[class^="box-item-message-"] pre'));
                for (const pre of pres) {
                    let box = pre.parentElement;
                    while (box) {
                        const cls = (box.className || '').toString();
                        if (cls.includes('box-item-') && !cls.includes('box-item-message-')) break;
                        box = box.parentElement;
                    }
                    const cls = box && (box.className || '').toString();
                    out.push({
                        sender: cls && cls.includes('is-me-') ? 'me' : 'peer',
                        text: (pre.innerText || '').trim(),
                        timestamp_str: ''
                    });
                }
                return out;
            }"""
        )
        return [
            ChatMessage(
                sender=str(row.get("sender") or "peer"),
                text=str(row.get("text") or ""),
                timestamp_str=str(row.get("timestamp_str") or ""),
            )
            for row in rows
            if str(row.get("text") or "").strip()
        ]

"""Background scheduler for message polling."""
from __future__ import annotations

import random
import threading
import traceback
from datetime import datetime, timedelta

from PyQt5.QtCore import QThread, pyqtSignal

from db.store import Store
from publisher.message_reader import MessageReader
from publisher.message_store import MessageStore


DEFAULT_POLL_INTERVAL_SECONDS = 60 * 60
INTER_ACCOUNT_DELAY_RANGE = (3.0, 8.0)


def should_trigger_interval(
    last_run: datetime | None,
    now: datetime,
    interval_seconds: int,
) -> bool:
    """Return True when interval_seconds elapsed since last_run."""
    if last_run is None:
        return False
    return now - last_run >= timedelta(seconds=interval_seconds)


class MessageScheduler(QThread):
    new_messages = pyqtSignal(int)
    refresh_done = pyqtSignal()
    account_status = pyqtSignal(int, str)

    def __init__(
        self,
        store: Store,
        msg_store: MessageStore,
        readers: dict[str, MessageReader],
        poll_interval_seconds: int = DEFAULT_POLL_INTERVAL_SECONDS,
        delay_range: tuple[float, float] = INTER_ACCOUNT_DELAY_RANGE,
    ):
        super().__init__()
        self._store = store
        self._msg_store = msg_store
        self._readers = readers
        self._poll_interval_seconds = poll_interval_seconds
        self._delay_range = delay_range
        self._stop = threading.Event()
        self._wake = threading.Event()
        self._pending_account_id: int | None = None
        self._last_run: datetime | None = None
        self._pending_lock = threading.Lock()

    def trigger_now(self, account_id: int | None = None) -> None:
        with self._pending_lock:
            self._pending_account_id = account_id
        self._wake.set()

    def stop(self) -> None:
        self._stop.set()
        self._wake.set()

    def run_one_round(self, only_account_id: int | None = None) -> int:
        """Synchronously fetch one polling round. Returns newly added count."""
        accounts = [
            account
            for account in self._store.list_accounts()
            if account["is_active"] == 1
        ]
        if only_account_id is not None:
            accounts = [account for account in accounts if account["id"] == only_account_id]

        new_total = 0
        for index, account in enumerate(accounts):
            if self._stop.is_set():
                break
            reader = self._readers.get(account["platform"])
            if reader is None:
                continue
            account_id = account["id"]
            if self._msg_store.is_busy(account_id):
                continue

            self._emit_status(account_id, "fetching")
            try:
                messages = reader.fetch_unread_strangers(
                    account_id,
                    account["display_name"],
                    account["profile_path"],
                )
                for message in messages:
                    if self._msg_store.upsert(message):
                        new_total += 1
                self._emit_status(account_id, "idle")
            except Exception:
                traceback.print_exc()
                self._emit_status(account_id, "error")

            if index < len(accounts) - 1:
                delay = random.uniform(*self._delay_range)
                if delay > 0 and self._stop.wait(timeout=delay):
                    break

        self._last_run = datetime.now()
        return new_total

    def _emit_status(self, account_id: int, status: str) -> None:
        try:
            self.account_status.emit(account_id, status)
        except Exception:
            pass

    def _emit_round_done(self, new_count: int) -> None:
        try:
            if new_count > 0:
                self.new_messages.emit(new_count)
            self.refresh_done.emit()
        except Exception:
            pass

    def run(self) -> None:
        self._last_run = datetime.now()
        while not self._stop.is_set():
            triggered = self._wake.wait(timeout=60.0)
            if self._stop.is_set():
                break
            if triggered:
                self._wake.clear()
                with self._pending_lock:
                    account_id = self._pending_account_id
                    self._pending_account_id = None
                new_count = self.run_one_round(only_account_id=account_id)
                self._emit_round_done(new_count)
                continue

            now = datetime.now()
            if should_trigger_interval(self._last_run, now, self._poll_interval_seconds):
                new_count = self.run_one_round()
                self._emit_round_done(new_count)

"""Abstract base for platform-specific private-message readers."""
from __future__ import annotations

from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from datetime import datetime


@dataclass
class Message:
    account_id: int
    account_name: str
    conversation_id: str
    user_name: str
    user_avatar_url: str
    preview: str
    timestamp_str: str
    fetched_at: datetime = field(default_factory=datetime.now)

    @property
    def key(self) -> str:
        return f"{self.account_id}_{self.conversation_id}"


@dataclass
class ChatMessage:
    sender: str
    text: str
    timestamp_str: str = ""


class MessageReader(ABC):
    platform: str = ""

    @abstractmethod
    def fetch_unread_strangers(
        self,
        account_id: int,
        account_name: str,
        profile_path: str,
    ) -> list[Message]:
        """Open a browser profile and scrape unread stranger messages.

        Implementations should handle platform/page errors internally and
        return an empty list when a fetch cannot be completed.
        """

    @abstractmethod
    def reply(self, profile_path: str, conversation_id: str, text: str) -> tuple[bool, str]:
        """Send a manual reply.

        Returns (success, error_msg). error_msg is an empty string on success.
        """

    @abstractmethod
    def fetch_conversation_messages(self, profile_path: str, conversation_id: str) -> list[ChatMessage]:
        """Read the visible history of one conversation."""

"""Persistent local message store plus processed-set."""
from __future__ import annotations

import json
import threading
from datetime import datetime
from pathlib import Path

from publisher.message_reader import Message


class MessageStore:
    """Thread-safe message state for the message-management tab.

    Messages are cached to JSON so the message-management tab is not empty
    after restarting MediaPush. The seen-set is a lightweight processed marker.
    """

    def __init__(self, seen_path: Path | str, messages_path: Path | str | None = None):
        self._seen_path = Path(seen_path)
        self._messages_path = Path(messages_path) if messages_path else self._seen_path.with_name("message_cache.json")
        self._lock = threading.Lock()
        self._messages: dict[str, Message] = self._load_messages()
        self._busy_accounts: set[int] = set()
        self._seen: dict[str, str] = self._load_seen()

    def _load_seen(self) -> dict[str, str]:
        if not self._seen_path.exists():
            return {}
        try:
            data = json.loads(self._seen_path.read_text(encoding="utf-8"))
        except Exception:
            return {}
        if not isinstance(data, dict):
            return {}
        return {str(k): str(v) for k, v in data.items()}

    def _save_seen(self) -> None:
        self._seen_path.parent.mkdir(parents=True, exist_ok=True)
        tmp = self._seen_path.with_suffix(self._seen_path.suffix + ".tmp")
        tmp.write_text(
            json.dumps(self._seen, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        tmp.replace(self._seen_path)

    def _load_messages(self) -> dict[str, Message]:
        if not self._messages_path.exists():
            return {}
        try:
            data = json.loads(self._messages_path.read_text(encoding="utf-8"))
        except Exception:
            return {}
        if not isinstance(data, list):
            return {}
        messages: dict[str, Message] = {}
        for row in data:
            try:
                fetched_raw = str(row.get("fetched_at") or "")
                fetched_at = datetime.fromisoformat(fetched_raw) if fetched_raw else datetime.now()
                msg = Message(
                    account_id=int(row["account_id"]),
                    account_name=str(row.get("account_name") or ""),
                    conversation_id=str(row["conversation_id"]),
                    user_name=str(row.get("user_name") or ""),
                    user_avatar_url=str(row.get("user_avatar_url") or ""),
                    preview=str(row.get("preview") or ""),
                    timestamp_str=str(row.get("timestamp_str") or ""),
                    fetched_at=fetched_at,
                )
            except Exception:
                continue
            messages[msg.key] = msg
        return messages

    def _save_messages(self) -> None:
        self._messages_path.parent.mkdir(parents=True, exist_ok=True)
        rows = []
        for msg in sorted(self._messages.values(), key=lambda item: item.fetched_at, reverse=True):
            rows.append(
                {
                    "account_id": msg.account_id,
                    "account_name": msg.account_name,
                    "conversation_id": msg.conversation_id,
                    "user_name": msg.user_name,
                    "user_avatar_url": msg.user_avatar_url,
                    "preview": msg.preview,
                    "timestamp_str": msg.timestamp_str,
                    "fetched_at": msg.fetched_at.isoformat(timespec="seconds"),
                }
            )
        tmp = self._messages_path.with_suffix(self._messages_path.suffix + ".tmp")
        tmp.write_text(json.dumps(rows, ensure_ascii=False, indent=2), encoding="utf-8")
        tmp.replace(self._messages_path)

    @staticmethod
    def _key(account_id: int, conversation_id: str) -> str:
        return f"{account_id}_{conversation_id}"

    def is_seen(self, account_id: int, conversation_id: str) -> bool:
        with self._lock:
            return self._key(account_id, conversation_id) in self._seen

    def mark_seen(self, account_id: int, conversation_id: str) -> None:
        key = self._key(account_id, conversation_id)
        with self._lock:
            self._seen[key] = datetime.now().isoformat(timespec="seconds")
            self._save_seen()
            self._save_messages()

    def remove(self, account_id: int, conversation_id: str) -> None:
        with self._lock:
            self._messages.pop(self._key(account_id, conversation_id), None)
            self._save_messages()

    def upsert(self, msg: Message) -> bool:
        """Add or update a message.

        Returns True when the row is new or its visible message content changed.
        """
        with self._lock:
            old = self._messages.get(msg.key)
            if old is not None and _same_visible_message(old, msg):
                return False
            self._messages[msg.key] = msg
            self._save_messages()
            return True

    def list_all(self) -> list[Message]:
        with self._lock:
            return sorted(
                self._messages.values(),
                key=lambda msg: msg.fetched_at,
                reverse=True,
            )

    def mark_busy(self, account_id: int) -> None:
        with self._lock:
            self._busy_accounts.add(account_id)

    def mark_idle(self, account_id: int) -> None:
        with self._lock:
            self._busy_accounts.discard(account_id)

    def is_busy(self, account_id: int) -> bool:
        with self._lock:
            return account_id in self._busy_accounts


def _same_visible_message(left: Message, right: Message) -> bool:
    return (
        left.account_name == right.account_name
        and left.user_name == right.user_name
        and left.user_avatar_url == right.user_avatar_url
        and left.preview == right.preview
        and left.timestamp_str == right.timestamp_str
    )

"""Douyin creator content cleanup helpers and browser automation."""
from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime, timedelta
from pathlib import Path
import re
from collections.abc import Callable, Iterable


@dataclass(frozen=True)
class WorkInfo:
    title: str
    publish_time: datetime | None
    plays: int | None
    likes: int | None
    has_detail_link: bool


@dataclass(frozen=True)
class ParsedWork(WorkInfo):
    publish_time_text: str
    plays_text: str
    likes_text: str


@dataclass(frozen=True)
class CleanupDecision:
    should_delete: bool
    reason: str


@dataclass(frozen=True)
class CleanupResult:
    account_id: int
    account_name: str
    title: str
    publish_time: str
    plays: str
    likes: str
    reason: str
    status: str
    detail: str = ""


def parse_count(raw: str | None) -> int | None:
    if raw is None:
        return None
    text = raw.strip().replace(",", "")
    if not text or text == "-":
        return None
    multiplier = 1
    if text.endswith("万"):
        multiplier = 10000
        text = text[:-1]
    try:
        return int(float(text) * multiplier)
    except ValueError:
        return None


def parse_publish_time(raw: str | None) -> datetime | None:
    if not raw:
        return None
    text = raw.strip()
    for fmt in ("%Y年%m月%d日 %H:%M", "%Y-%m-%d %H:%M", "%Y/%m/%d %H:%M"):
        try:
            return datetime.strptime(text, fmt)
        except ValueError:
            continue
    return None


def parse_work_from_row_text(text: str) -> ParsedWork:
    lines = [line.strip() for line in text.splitlines() if line.strip()]
    title = ""
    publish_time_text = ""
    plays_text = ""
    likes_text = ""

    time_re = re.compile(r"\d{4}年\d{1,2}月\d{1,2}日\s+\d{1,2}:\d{2}")
    duration_re = re.compile(r"^\d{1,2}:\d{2}(?::\d{2})?$")
    ignored_title_lines = {
        "播放",
        "点赞",
        "评论",
        "分享",
        "删除作品",
        "查看详情",
        "编辑作品",
        "作品置顶",
        "设置权限",
    }
    for index, line in enumerate(lines):
        if not title and line not in ignored_title_lines and not duration_re.match(line):
            if not time_re.search(line):
                title = line
        if not publish_time_text:
            match = time_re.search(line)
            if match:
                publish_time_text = match.group(0)
        if line == "播放" and index + 1 < len(lines):
            plays_text = lines[index + 1]
        if line == "点赞" and index + 1 < len(lines):
            likes_text = lines[index + 1]

    return ParsedWork(
        title=title,
        publish_time=parse_publish_time(publish_time_text),
        publish_time_text=publish_time_text,
        plays=parse_count(plays_text),
        plays_text=plays_text,
        likes=parse_count(likes_text),
        likes_text=likes_text,
        has_detail_link="查看详情" in text,
    )


def choose_cleanup_action(work: WorkInfo, now: datetime | None = None) -> CleanupDecision:
    now = now or datetime.now()
    if work.has_detail_link:
        return CleanupDecision(True, "限流查看详情")

    if work.publish_time is None:
        return CleanupDecision(False, "发布时间缺失跳过")
    if now - work.publish_time < timedelta(hours=24):
        return CleanupDecision(False, "24小时内跳过")

    if work.plays is None or work.likes is None:
        return CleanupDecision(False, "指标缺失跳过")
    if work.plays < 1000 and work.likes < 30:
        return CleanupDecision(True, "低播放低点赞")
    return CleanupDecision(False, "数据达标跳过")


def matches_retry_target(work: WorkInfo, target_title: str = "", target_publish_time: str = "") -> bool:
    title = (target_title or "").strip()
    publish_time = (target_publish_time or "").strip()
    if not title and not publish_time:
        return True
    if title and work.title.strip() != title:
        return False
    if publish_time:
        expected = parse_publish_time(publish_time)
        if expected is None or work.publish_time != expected:
            return False
    return True


def is_active_douyin_account(account: dict) -> bool:
    return account.get("platform") == "douyin" and int(account.get("is_active") or 0) == 1


DOUYIN_CONTENT_MANAGE_URL = "https://creator.douyin.com/creator-micro/content/manage"
LOGIN_URL_MARKERS = ("/login", "/passport")
NAV_TIMEOUT_MS = 30_000
ROW_WAIT_MS = 20_000
STEP_TIMEOUT_MS = 8_000

CONFIRM_DELETE_SELECTORS = [
    ".semi-modal button:has-text('确定')",
    ".semi-modal button:has-text('确认')",
    "[role='dialog'] button:has-text('确定')",
    "[role='dialog'] button:has-text('确认')",
    "button:has-text('确定')",
    "button:has-text('确认')",
]

BLOCKING_SELECTORS = [
    "text=验证码",
    "text=安全验证",
    "text=身份验证",
    "text=请完成验证",
    "text=登录",
]


def _logs_dir() -> Path:
    base = Path(__file__).resolve().parent.parent / "logs"
    base.mkdir(exist_ok=True)
    return base


def _shoot(page, step: str) -> str:
    try:
        out = _logs_dir() / f"douyin-cleanup-{step}-{datetime.now().strftime('%Y%m%d-%H%M%S')}.png"
        page.screenshot(path=str(out), full_page=True)
        return str(out)
    except Exception:
        return ""


def _first_visible(page, selectors: list[str], timeout_ms: int = 300):
    for sel in selectors:
        try:
            loc = page.locator(sel).first
            loc.wait_for(state="visible", timeout=timeout_ms)
            return loc
        except Exception:
            continue
    return None


def _blocking_reason(page) -> str:
    if any(marker in page.url for marker in LOGIN_URL_MARKERS):
        return f"账号登录失效: {page.url}"
    loc = _first_visible(page, BLOCKING_SELECTORS, timeout_ms=200)
    if loc is None:
        return ""
    try:
        text = loc.inner_text(timeout=500).strip()
    except Exception:
        text = "页面出现验证/登录提示"
    return text or "页面出现验证/登录提示"


def _confirm_delete_dialog(page) -> None:
    loc = _first_visible(page, CONFIRM_DELETE_SELECTORS, timeout_ms=1500)
    if loc is not None:
        loc.click(timeout=STEP_TIMEOUT_MS)


class DouyinCleanupRunner:
    def __init__(
        self,
        accounts: Iterable[dict],
        clean_account: Callable[[dict, Callable[[], bool]], Iterable[CleanupResult]] | None = None,
        stop_requested: Callable[[], bool] | None = None,
    ):
        self._accounts = list(accounts)
        self._clean_account = clean_account or self._default_clean_account
        self._stop_requested = stop_requested or (lambda: False)

    def run(self) -> Iterable[CleanupResult]:
        for account in self._accounts:
            if self._stop_requested():
                break
            if not is_active_douyin_account(account):
                continue
            yield from self._clean_account(account, self._stop_requested)

    @staticmethod
    def _default_clean_account(account: dict, stop_requested: Callable[[], bool]) -> Iterable[CleanupResult]:
        return DouyinWorkCleaner().clean_account(account, stop_requested=stop_requested)


class DouyinWorkCleaner:
    def clean_account(
        self,
        account: dict,
        stop_requested: Callable[[], bool] | None = None,
        limit: int = 30,
        target_title: str = "",
        target_publish_time: str = "",
    ) -> list[CleanupResult]:
        from playwright.sync_api import sync_playwright

        stop_requested = stop_requested or (lambda: False)
        account_id = int(account.get("id") or 0)
        account_name = str(account.get("display_name") or account_id)
        profile_path = str(account.get("profile_path") or "")
        if not profile_path:
            return [
                CleanupResult(
                    account_id=account_id,
                    account_name=account_name,
                    title="",
                    publish_time="",
                    plays="",
                    likes="",
                    reason="账号配置缺失",
                    status="失败",
                    detail="这个账号没有本地浏览器 Profile 路径",
                )
            ]

        results: list[CleanupResult] = []
        processed: set[str] = set()

        try:
            with sync_playwright() as p:
                ctx = p.chromium.launch_persistent_context(
                    user_data_dir=Path(profile_path).as_posix(),
                    headless=False,
                    viewport={"width": 1280, "height": 900},
                )
                try:
                    page = ctx.new_page() if not ctx.pages else ctx.pages[0]
                    page.set_default_timeout(STEP_TIMEOUT_MS)
                    page.goto(DOUYIN_CONTENT_MANAGE_URL, wait_until="domcontentloaded", timeout=NAV_TIMEOUT_MS)
                    page.wait_for_timeout(1500)

                    reason = _blocking_reason(page)
                    if reason:
                        shot = _shoot(page, f"blocked-{account_id}")
                        return [
                            CleanupResult(account_id, account_name, "", "", "", "", reason, "失败", shot)
                        ]

                    page.locator("text=删除作品").first.wait_for(state="visible", timeout=ROW_WAIT_MS)
                    stagnant_passes = 0
                    while len(processed) < limit and not stop_requested():
                        deleted_this_pass = False
                        found_new = False
                        delete_buttons = page.locator("text=删除作品")
                        count = min(delete_buttons.count(), max(0, limit - len(processed)))
                        for index in range(count):
                            if stop_requested() or len(processed) >= limit:
                                break
                            delete_button = delete_buttons.nth(index)
                            row = self._row_for_delete_button(delete_button)
                            row_text = row.inner_text(timeout=STEP_TIMEOUT_MS)
                            work = parse_work_from_row_text(row_text)
                            if not matches_retry_target(work, target_title, target_publish_time):
                                continue
                            key = f"{work.title}|{work.publish_time_text}"
                            if not key.strip("|") or key in processed:
                                continue
                            processed.add(key)
                            found_new = True

                            decision = choose_cleanup_action(work)
                            if not decision.should_delete:
                                results.append(
                                    self._result(account_id, account_name, work, decision.reason, "跳过")
                                )
                                continue

                            try:
                                delete_button.click(timeout=STEP_TIMEOUT_MS)
                                _confirm_delete_dialog(page)
                                page.wait_for_timeout(1800)
                                results.append(
                                    self._result(account_id, account_name, work, decision.reason, "已删除")
                                )
                                deleted_this_pass = True
                                break
                            except Exception as exc:
                                shot = _shoot(page, f"delete-failed-{account_id}")
                                results.append(
                                    self._result(
                                        account_id,
                                        account_name,
                                        work,
                                        decision.reason,
                                        "失败",
                                        f"{type(exc).__name__}: {exc}; screenshot={shot}",
                                    )
                                )

                        if deleted_this_pass:
                            stagnant_passes = 0
                            continue
                        if len(processed) >= limit:
                            break
                        if not found_new:
                            stagnant_passes += 1
                        else:
                            stagnant_passes = 0
                        if stagnant_passes >= 2:
                            break
                        page.mouse.wheel(0, 900)
                        page.wait_for_timeout(1000)
                    if target_title or target_publish_time:
                        matched = any(
                            r.title == target_title and (not target_publish_time or r.publish_time == target_publish_time)
                            for r in results
                        )
                        if not matched:
                            results.append(
                                CleanupResult(
                                    account_id=account_id,
                                    account_name=account_name,
                                    title=target_title,
                                    publish_time=target_publish_time,
                                    plays="",
                                    likes="",
                                    reason="重试失败",
                                    status="失败",
                                    detail="未在作品管理页找到原作品",
                                )
                            )
                finally:
                    ctx.close()
        except Exception as exc:
            results.append(
                CleanupResult(
                    account_id=account_id,
                    account_name=account_name,
                    title="",
                    publish_time="",
                    plays="",
                    likes="",
                    reason="账号清理失败",
                    status="失败",
                    detail=f"{type(exc).__name__}: {exc}",
                )
            )
        return results

    @staticmethod
    def _row_for_delete_button(delete_button):
        return delete_button.locator(
            "xpath=ancestor::div[contains(., '播放') and contains(., '点赞')][1]"
        )

    @staticmethod
    def _result(
        account_id: int,
        account_name: str,
        work: ParsedWork,
        reason: str,
        status: str,
        detail: str = "",
    ) -> CleanupResult:
        return CleanupResult(
            account_id=account_id,
            account_name=account_name,
            title=work.title,
            publish_time=work.publish_time_text,
            plays=work.plays_text,
            likes=work.likes_text,
            reason=reason,
            status=status,
            detail=detail,
        )

